#include "ezlocalai/ctts.hpp"
#include "whisper_transcription_test.hpp"
#include <zlib.h>
#include <thread>
#include <iomanip>
using namespace transcription_test;
using Ordered=nlohmann::ordered_json;
std::string hex_bytes(const std::string &input) { std::string out; const char *digits="0123456789abcdef"; for(unsigned char c:input) {out+=digits[c>>4];out+=digits[c&15];} return out; }
std::string substitute(std::string value,const std::string &from,const std::string &to) {size_t at=0;while((at=value.find(from,at))!=std::string::npos){value.replace(at,from.size(),to);at+=to.size();}return value;}
Json tree(const fs::path &root) {Json out=Json::object();for(const auto &entry:fs::recursive_directory_iterator(root,fs::directory_options::skip_permission_denied)){const auto p=entry.path();const auto key=p.lexically_relative(root).string();if(entry.is_symlink())out[key]={{"kind","symlink"},{"target",fs::read_symlink(p).string()}};else if(entry.is_directory())out[key]={{"kind","dir"}};else {Json bytes;try{bytes=hex_bytes(read(p));}catch(const std::exception &){}out[key]={{"kind","file"},{"data",bytes}};}}return out;}
void setup(const Ordered &entry) {const fs::path path=entry.at("path").get<std::string>();if(!path.parent_path().empty())fs::create_directories(path.parent_path());if(entry.at("kind")=="dir")fs::create_directories(path);else if(entry.at("kind")=="symlink")fs::create_symlink(entry.at("target").get<std::string>(),path);else{std::ofstream out(path,std::ios::binary);out<<unhex(entry.at("data"));out.close();if(entry.contains("mode"))fs::permissions(path,fs::perms(entry.at("mode").get<unsigned>()));}}
void fail(const Ordered &action) {if(action.contains("error")){const auto &e=action.at("error");throw TtsError(e.value("category",std::string("RuntimeError")),e.at("message"));}}
struct Model:CttsBackend {int id=0;bool closed=false;};
int main(int argc,char **argv) {try {
 expect(argc==4,"source, fixture and pinned libsndfile");gzFile file=gzopen(argv[2],"rb");expect(file,"open gzip");std::string content;char buffer[65536];int size;while((size=gzread(file,buffer,sizeof(buffer)))>0)content.append(buffer,size);const auto end=gzclose(file);expect(size==0&&end==Z_OK,"complete gzip");std::istringstream input(content);std::string line;std::getline(input,line);const auto header=Json::parse(line);for(const auto &item:std::vector<std::pair<std::string,std::string>>{{"CTTS.py","source_sha256"},{"AudioCache.py","cache_sha256"},{"LlamaTTS.py","llama_sha256"}})expect(hash(read(fs::path(argv[1])/"ezlocalai"/item.first))==header.at(item.second),"pinned "+item.first);expect(hash(read(argv[3]))==header.at("libsndfile_sha256"),"pinned audio encoder");
 const auto original=fs::current_path();size_t cases=0,operations=0;
 while(std::getline(input,line)){if(line.empty())continue;const auto row=Ordered::parse(line);++cases;Temporary temporary;fs::current_path(temporary.path);struct Restore{fs::path path;~Restore(){fs::current_path(path);}}restore{original};const auto root=temporary.path;for(const auto &entry:row.at("setup"))setup(entry);
 Ordered environment=row.at("env");Json events=Json::array();const auto main=std::this_thread::get_id();size_t clock=0,uuid=0,generation=0,loads=0;std::vector<std::shared_ptr<Model>> models;std::unique_ptr<Ctts> owner;
 const auto event=[&](const std::string &name,Json args=Json::array()){Json entry=Json::array({name,std::this_thread::get_id()==main});for(const auto &arg:args)entry.push_back(arg);events.push_back(entry);};
 const auto directories=[] {Json out=Json::object();for(const auto name:{"outputs","voices","outputs/cache/audio","outputs/cache/metadata"})out[name]=fs::is_directory(name);return out;};
 CttsServiceOperations ops;ops.runtime.environment=[&](const std::string &key)->std::optional<std::string>{event("env",Json::array({key}));return environment.contains(key)?std::optional<std::string>(environment[key].get<std::string>()):std::nullopt;};
 ops.runtime.cuda_available=[&]{event("available");return row.at("hardware").value("available",false);};ops.runtime.memory_info=[&](const auto &index){event("memory",Json::array({index}));return std::pair<double,double>{8000.*1048576,16000.*1048576};};
 ops.runtime.collect=[&]{event("collect");};ops.runtime.empty_cache=[&]{event("empty_cache");};ops.runtime.synchronize=[&]{event("synchronize");};ops.runtime.ipc_collect=[&]{event("ipc_collect");};ops.runtime.inference_mode=[&]{event("enter");return [&](const std::string &category){event("exit",Json::array({category}));};};
 ops.runtime.load=[&](const auto &device,const auto &kwargs){event("load",Json::array({device,Json::parse(kwargs),directories()}));const auto index=loads++;if(index<row.at("loads").size())fail(row["loads"][index]);auto model=std::make_shared<Model>();model->id=models.size()+1;auto *raw=model.get();model->close=[&,raw]{event("close",Json::array({raw->id}));raw->closed=true;};model->generate=[&,raw](const std::string &request){event("generate",Json::array({raw->id,Json::parse(request),directories()}));const auto index=generation++;const auto action=index<row.at("generations").size()?row["generations"][index]:Ordered::object();fail(action);CttsGenerated result;result.audio.push_back({action.value("samples",std::vector<float>{0,.25f,-.5f,1.25f,-1.25f}),"",action.value("channels",1)});result.rate_json=action.value("rate_json",std::string("24000"));return result;};models.push_back(model);return model;};
 ops.cache.now=[&]{expect(clock<row.at("now_values").size(),"clock count");const auto value=row.at("now_values")[clock++].get<std::string>();event("now",Json::array({value}));return value;};ops.uuid_hex=[&]{std::ostringstream out;out<<std::hex<<std::setfill('0')<<std::setw(32)<<++uuid;const auto value=out.str();event("uuid",Json::array({value}));return value;};
 const auto snapshot=[&]{Json all=Json::array();for(const auto &model:models)all.push_back({{"id",model->id},{"closed",model->closed}});Json state;if(owner){const auto current=owner->runtime().backend();state={{"voices",owner->voices()},{"sample_rate",owner->sample_rate()},{"use_cache",Json::parse(owner->use_cache_json())},{"device",owner->runtime().device()},{"closed",owner->runtime().closed()},{"model",current?Json(std::static_pointer_cast<Model>(current)->id):Json()},{"cache_config",Json::parse(owner->cache().configuration())},{"cache_stats",Json::parse(owner->cache().raw_statistics())}};}return Json{{"files",tree(root)},{"events",events},{"now_calls",clock},{"uuid_calls",uuid},{"models",all},{"state",state}};};
 const auto normalize=[&](const Json &v){return Json::parse(substitute(v.dump(),root.string(),"<ROOT>"));};Json startup;
 try{owner=std::make_unique<Ctts>(substitute(row.at("config").dump(),"<ROOT>",root.string()),row.at("device").dump(),ops);startup["value"]=snapshot();}catch(const TtsError &e){startup={{"error",{e.category,e.what()}},{"state",snapshot()}};}
 compare_json(normalize(startup),row.at("startup"),"startup "+std::to_string(cases)+" "+row.at("name").get<std::string>());
 if(owner){size_t index=0;for(const auto &action:row.at("operations")){++operations;const auto kind=action.at("op").get<std::string>();Json result={{"value",nullptr}};try{
 if(kind=="generate")result["value"]=owner->generate(action.at("request").dump());else if(kind=="close")owner->close();else if(kind=="clear")owner->cache().clear(action.contains("voice")?std::optional<std::string>(action.at("voice").get<std::string>()):std::nullopt);else if(kind=="stats")result["value"]=Json::parse(owner->cache().statistics());else if(kind=="env")environment.update(action.at("values"));else if(kind=="file")setup(action.at("entry"));else if(kind=="remove")fs::remove(action.at("path").get<std::string>());else if(kind=="seed"){const auto key=action.at("key").get<std::string>();fs::create_directories("outputs/cache/audio");std::ofstream out("outputs/cache/audio/"+key+".wav",std::ios::binary);out<<unhex(action.at("data"));out.close();if(action.at("metadata")!="missing"){fs::create_directories("outputs/cache/metadata");std::ofstream meta("outputs/cache/metadata/"+key+".json");if(action.at("metadata")=="invalid")meta<<"invalid";else meta<<"{\"created_at\": \""<<(action.at("metadata")=="expired"?"2000-01-01":"2026-10-17T12:00:00")<<"\", \"voice\": \"default\"}";}}
 }catch(const TtsError &e){result={{"error",{e.category,e.what()}}};}result["state"]=snapshot();const auto expected=row.at("results")[index++];compare_json(normalize(result),expected,"case "+std::to_string(cases)+" "+row.at("name").get<std::string>()+" operation "+std::to_string(index));}}
 }
 expect(cases==header.at("cases")&&operations==header.at("operations"),"complete buffered generation comparisons");std::cout<<cases<<" complete CTTS constructor/generation scenarios and "<<operations<<" operations match\n";return 0;
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
